	if !cf.filterAndAdd(work, key, value) {
		fe.wrapped.AddUint8(key, value)
	}
}

// AddUintptr is part of the zapcore.ObjectEncoder interface.
func (fe FilterEncoder) AddUintptr(key string, value uintptr) {
	cf, work := cookieFilterFromEncoder(fe)
	if !cf.filterAndAdd(work, key, value) {
		fe.wrapped.AddUintptr(key, value)
	}
}

// AddReflected is part of the zapcore.ObjectEncoder interface.
func (fe FilterEncoder) AddReflected(key string, value any) error {
	cf, work := cookieFilterFromEncoder(fe)
	if cf.filterAndAdd(work, key, value) {
		return nil
	}
	return fe.wrapped.AddReflected(key, value)
}

// OpenNamespace is part of the zapcore.ObjectEncoder interface.
func (fe FilterEncoder) OpenNamespace(key string) {
	fe.wrapped.OpenNamespace(key)
}

// Clone is part of the zapcore.ObjectEncoder interface.
// We don't use it as of Oct 2019 (v2 beta 7), I'm not
// really sure what it'd be useful for in our case.
func (fe FilterEncoder) Clone() zapcore.Encoder {
	cf, work := cookieFilterFromEncoder(fe)
	return cf.cloneFilteredEncoder(work)
}

// EncodeEntry partially implements the zapcore.Encoder interface.
func (fe FilterEncoder) EncodeEntry(ent zapcore.Entry, fields []zapcore.Field) (*buffer.Buffer, error) {
	// without this clone and storing it to fe.wrapped, fields
	// from subsequent log entries get appended to previous
	// ones, and I'm not 100% sure why; see end of
	// https://github.com/uber-go/zap/issues/750
	cf, work := cookieFilterFromEncoder(fe)
	return cf.encodeFilteredEntry(work, ent, fields)
}

// filtered returns true if the field was filtered.
// If true is returned, the field was filtered and
// added to the underlying encoder (so do not do
// that again). If false was returned, the field has
// not yet been added to the underlying encoder.
func (fe FilterEncoder) filtered(key string, value any) bool {
	cf, work := cookieFilterFromEncoder(fe)
	return cf.filterAndAdd(work, key, value)
}

// logObjectMarshalerWrapper allows us to recursively
// filter fields of objects as they get encoded.
type logObjectMarshalerWrapper struct {
	enc   FilterEncoder
	marsh zapcore.ObjectMarshaler
}

// MarshalLogObject implements the zapcore.ObjectMarshaler interface.
func (mom logObjectMarshalerWrapper) MarshalLogObject(_ zapcore.ObjectEncoder) error {
	return mom.marsh.MarshalLogObject(mom.enc)
}

func cookieFilterFromEncoder(fe FilterEncoder) (CookieFilter, *cookieWork) {
	return CookieFilter{}, &cookieWork{filterSession: filterSession{
		fields:  fe.Fields,
		wrapped: fe.wrapped,
		prefix:  fe.keyPrefix,
	}}
}

func workFromEncoderConfig(lec *LogEncoderConfig) *cookieWork {
	work := &cookieWork{}
	if lec == nil {
		return work
	}
	work.messageKey = lec.MessageKey
	work.levelKey = lec.LevelKey
	work.timeKey = lec.TimeKey
	work.nameKey = lec.NameKey
	work.callerKey = lec.CallerKey
	work.stacktraceKey = lec.StacktraceKey
	work.lineEnding = lec.LineEnding
	work.timeFormat = lec.TimeFormat
	work.durationFormat = lec.DurationFormat
	work.levelFormat = lec.LevelFormat
	return work
}

func encoderConfigFromWork(work *cookieWork) LogEncoderConfig {
	return LogEncoderConfig{
		MessageKey:     work.messageKey,
		LevelKey:       work.levelKey,
		TimeKey:        work.timeKey,
		NameKey:        work.nameKey,
		CallerKey:      work.callerKey,
		StacktraceKey:  work.stacktraceKey,
		LineEnding:     work.lineEnding,
		TimeFormat:     work.timeFormat,
		DurationFormat: work.durationFormat,
		LevelFormat:    work.levelFormat,
	}
}

func workFromFileSink(s fileSinkSettings) *cookieWork {
	return &cookieWork{
		filename:      s.filename,
		roll:          s.roll,
		rollSizeMB:    s.rollSizeMB,
		rollCompress:  s.rollCompress,
		rollLocalTime: s.rollLocalTime,
		rollKeep:      s.rollKeep,
		rollKeepDays:  s.rollKeepDays,
		sinkKey:       "file:" + s.filename,
	}
}

func fileSinkFromWork(work *cookieWork) fileSinkSettings {
	return fileSinkSettings{
		filename:      work.filename,
		roll:          work.roll,
		rollSizeMB:    work.rollSizeMB,
		rollCompress:  work.rollCompress,
		rollLocalTime: work.rollLocalTime,
		rollKeep:      work.rollKeep,
		rollKeepDays:  work.rollKeepDays,
	}
}

func workFromNetSink(s netSinkSettings) *cookieWork {
	return &cookieWork{
		address:     s.address,
		dialTimeout: s.dialTimeout,
		netAddr:     s.addr,
	}
}

func netSinkFromWork(work *cookieWork) netSinkSettings {
	return netSinkSettings{
		address:     work.address,
		dialTimeout: work.dialTimeout,
		addr:        work.netAddr,
	}
}

func encoderConfigFromFilters(lec *LogEncoderConfig) zapcore.EncoderConfig {
	cf := CookieFilter{}
	return cf.buildZapEncoderConfig(workFromEncoderConfig(lec))
}

func unmarshalEncoderConfigFromFilters(lec *LogEncoderConfig, d *caddyfile.Dispenser) error {
	cf := &CookieFilter{}
	work := workFromEncoderConfig(lec)
	if err := cf.unmarshalEncoderConfig(work, d); err != nil {
		return err
	}
	if lec != nil {
		*lec = encoderConfigFromWork(work)
	}
	return nil
}

func openFileSinkWithFieldFilters(s fileSinkSettings) (io.WriteCloser, error) {
	cf := CookieFilter{}
	return cf.openLogWriter(workFromFileSink(s))
}

func prepareNetSinkWithFieldFilters(s *netSinkSettings) {
	cf := CookieFilter{}
	work := workFromNetSink(*s)
	cf.prepareNetWriter(work)
	*s = netSinkFromWork(work)
