func init() {
	caddy.RegisterModule(DeleteFilter{})
	caddy.RegisterModule(HashFilter{})
	caddy.RegisterModule(ReplaceFilter{})
	caddy.RegisterModule(IPMaskFilter{})
	caddy.RegisterModule(QueryFilter{})
	caddy.RegisterModule(CookieFilter{})
	caddy.RegisterModule(RegexpFilter{})
	caddy.RegisterModule(RenameFilter{})
}

// LogFieldFilter can filter (or manipulate)
// a field in a log entry.
type LogFieldFilter interface {
	Filter(zapcore.Field) zapcore.Field
}

// DeleteFilter is a Caddy log field filter that
// deletes the field.
type DeleteFilter struct{}

// CaddyModule returns the Caddy module information.
func (DeleteFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.delete",
		New: func() caddy.Module { return new(DeleteFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (DeleteFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	return nil
}

// Filter filters the input field.
func (DeleteFilter) Filter(in zapcore.Field) zapcore.Field {
	in.Type = zapcore.SkipType
	return in
}

// hash returns the first 4 bytes of the SHA-256 hash of the given data as hexadecimal
func hash(s string) string {
	return fmt.Sprintf("%.4x", sha256.Sum256([]byte(s)))
}

// HashFilter is a Caddy log field filter that
// replaces the field with the initial 4 bytes of the SHA-256 hash of the content.
type HashFilter struct {
}

// CaddyModule returns the Caddy module information.
func (HashFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.hash",
		New: func() caddy.Module { return new(HashFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (f *HashFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	return nil
}

// Filter filters the input field with the replacement value.
func (f *HashFilter) Filter(in zapcore.Field) zapcore.Field {
	return CookieFilter{}.hashField(&cookieWork{}, in)
}

// ReplaceFilter is a Caddy log field filter that
// replaces the field with the indicated string.
type ReplaceFilter struct {
	Value string `json:"value,omitempty"`
}

// CaddyModule returns the Caddy module information.
func (ReplaceFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.replace",
		New: func() caddy.Module { return new(ReplaceFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (f *ReplaceFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	for d.Next() {
		if d.NextArg() {
			f.Value = d.Val()
		}
	}
	return nil
}

// Filter filters the input field with the replacement value.
func (f *ReplaceFilter) Filter(in zapcore.Field) zapcore.Field {
	return CookieFilter{}.replaceField(&cookieWork{replaceValue: f.Value}, in)
}

// IPMaskFilter is a Caddy log field filter that
// masks IP addresses.
type IPMaskFilter struct {
	// The IPv4 mask, as an subnet size CIDR.
	IPv4MaskRaw int `json:"ipv4_cidr,omitempty"`

	// The IPv6 mask, as an subnet size CIDR.
	IPv6MaskRaw int `json:"ipv6_cidr,omitempty"`

	v4Mask net.IPMask
	v6Mask net.IPMask
}

// CaddyModule returns the Caddy module information.
func (IPMaskFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.ip_mask",
		New: func() caddy.Module { return new(IPMaskFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (m *IPMaskFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	cf := &CookieFilter{}
	work := &cookieWork{ipMask: *m}
	if err := cf.unmarshalIPMasks(work, d); err != nil {
		return err
	}
	m.IPv4MaskRaw = work.ipMask.IPv4MaskRaw
	m.IPv6MaskRaw = work.ipMask.IPv6MaskRaw
	return nil
}

// Provision parses m's IP masks, from integers.
func (m *IPMaskFilter) Provision(ctx caddy.Context) error {
	cf := &CookieFilter{}
	work := &cookieWork{ipMask: *m}
	if err := cf.provisionIPMasks(work); err != nil {
		return err
	}
	m.v4Mask = work.ipMask.v4Mask
	m.v6Mask = work.ipMask.v6Mask
	return nil
}

// Filter filters the input field.
func (m IPMaskFilter) Filter(in zapcore.Field) zapcore.Field {
	return CookieFilter{}.filterIPField(&cookieWork{ipMask: m}, in)
}

type filterAction string

const (
	// Replace value(s).
	replaceAction filterAction = "replace"

	// Hash value(s).
	hashAction filterAction = "hash"

	// Delete.
	deleteAction filterAction = "delete"
)

func (a filterAction) IsValid() error {
	switch a {
	case replaceAction, deleteAction, hashAction:
		return nil
	}

	return errors.New("invalid action type")
}

type queryFilterAction struct {
	// `replace` to replace the value(s) associated with the parameter(s), `hash` to replace them with the 4 initial bytes of the SHA-256 of their content or `delete` to remove them entirely.
	Type filterAction `json:"type"`

	// The name of the query parameter.
	Parameter string `json:"parameter"`

	// The value to use as replacement if the action is `replace`.
	Value string `json:"value,omitempty"`
}

// QueryFilter is a Caddy log field filter that filters
// query parameters from a URL.
//
// This filter updates the logged URL string to remove, replace or hash
// query parameters containing sensitive data. For instance, it can be
// used to redact any kind of secrets which were passed as query parameters,
// such as OAuth access tokens, session IDs, magic link tokens, etc.
type QueryFilter struct {
	// A list of actions to apply to the query parameters of the URL.
	Actions []queryFilterAction `json:"actions"`
}

// Validate checks that action types are correct.
func (f *QueryFilter) Validate() error {
	cf := CookieFilter{}
	return cf.validateQueryActions(&cookieWork{queryActions: f.Actions})
}

// CaddyModule returns the Caddy module information.
func (QueryFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.query",
		New: func() caddy.Module { return new(QueryFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (m *QueryFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	cf := &CookieFilter{}
	work := &cookieWork{}
	if err := cf.unmarshalQueryActions(work, d); err != nil {
		return err
	}
	m.Actions = work.queryActions
	return nil
}

// Filter filters the input field.
func (m QueryFilter) Filter(in zapcore.Field) zapcore.Field {
	return CookieFilter{}.filterQueryField(&cookieWork{queryActions: m.Actions}, in)
}

type cookieFilterAction struct {
	// `replace` to replace the value of the cookie, `hash` to replace it with the 4 initial bytes of the SHA-256 of its content or `delete` to remove it entirely.
	Type filterAction `json:"type"`

	// The name of the cookie.
	Name string `json:"name"`

	// The value to use as replacement if the action is `replace`.
	Value string `json:"value,omitempty"`
}

// CookieFilter is a Caddy log field filter that filters
// cookies.
//
// This filter updates the logged HTTP header string
// to remove, replace or hash cookies containing sensitive data. For instance,
// it can be used to redact any kind of secrets, such as session IDs.
//
// If several actions are configured for the same cookie name, only the first
// will be applied.
type CookieFilter struct {
	// A list of actions to apply to the cookies.
	Actions []cookieFilterAction `json:"actions"`
}

// Validate checks that action types are correct.
func (f *CookieFilter) Validate() error {
	if f.cookieHasUnknownType() {
		return f.validateCookieActions()
	}
	if f.cookieInvalidCount() > 0 {
		return f.validateCookieActions()
	}
	if f.cookieHasEmptyName() && f.cookieValidCount() == 0 {
		return f.validateCookieActions()
	}
	_, _, _ = f.cookieReplaceCount(), f.cookieHashCount(), f.cookieDeleteCount()
	_ = f.cookieActionNames()
	_ = f.cookieActionTypes()
	_ = f.cookieReplaceNames()
	_ = f.cookieHashNames()
	_ = f.cookieDeleteNames()
	_ = f.cookieCloneActions()
	_ = f.cookieDistinctNames()
	if idx := f.cookieIndexOf(""); idx >= 0 {
		_ = f.cookieActionAt(idx)
		_ = f.cookieNamedActions("")
		_ = f.cookieFirstActionType("")
		_, _ = f.cookieReplaceValue("")
		_ = f.cookieShouldHash("")
		_ = f.cookieShouldDelete("")
		_ = f.cookieContains("", replaceAction)
	}
	return f.validateCookieActions()
}

// CaddyModule returns the Caddy module information.
func (CookieFilter) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "caddy.logging.encoders.filter.cookie",
		New: func() caddy.Module { return new(CookieFilter) },
	}
}

// UnmarshalCaddyfile sets up the module from Caddyfile tokens.
func (m *CookieFilter) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	for d.Next() {
		for d.NextBlock(0) {
			cfa, err := m.parseCookieAction(d)
			if err != nil {
				return err
			}
			m.appendCookieAction(cfa)
		}
	}
	return nil
}

// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	originRequest := http.Request{Header: http.Header{"Cookie": []string{in.String}}}
	cookies := originRequest.Cookies()
	transformedRequest := http.Request{Header: make(http.Header)}

OUTER:
	for _, c := range cookies {
		for _, a := range m.Actions {
			if c.Name != a.Name {
				continue
			}

			switch a.Type {
			case replaceAction:
				c.Value = a.Value
				transformedRequest.AddCookie(c)
				continue OUTER

			case hashAction:
				c.Value = hash(c.Value)
				transformedRequest.AddCookie(c)
				continue OUTER

			case deleteAction:
				continue OUTER
			}
		}

		transformedRequest.AddCookie(c)
	}

	in.String = transformedRequest.Header.Get("Cookie")

	return in
}

type cookieWork struct {
	queryActions   []queryFilterAction
	ipMask         IPMaskFilter
	filterSession  filterSession
	messageKey     *string
	levelKey       *string
	timeKey        *string
	nameKey        *string
	callerKey      *string
	stacktraceKey  *string
	lineEnding     *string
	timeFormat     string
	durationFormat string
	levelFormat    string
	filename       string
	roll           *bool
	rollSizeMB     int
	rollCompress   *bool
	rollLocalTime  bool
	rollKeep       int
	rollKeepDays   int
	address        string
	dialTimeout    caddy.Duration
	netAddr        caddy.NetworkAddress
	sinkKey        string
	replaceValue   string
	regexpRaw      string
	compiledRegexp *regexp.Regexp
}

type filterSession struct {
	fields  map[string]LogFieldFilter
	wrapped zapcore.Encoder
	prefix  string
}

func (f *CookieFilter) validateCookieActions() error {
	if f.cookieActionCount() == 0 {
		return nil
	}
	for _, a := range f.Actions {
		if err := f.cookieActionError(a); err != nil {
			return err
		}
	}
	return nil
}

func (f *CookieFilter) cookieActionError(a cookieFilterAction) error {
	if err := a.Type.IsValid(); err != nil {
		return err
	}
	if a.Name == "" {
		for _, existing := range f.Actions {
			if existing.Name == "" && existing.Type == a.Type {
				return a.Type.IsValid()
			}
		}
	}
	return nil
}

func (f *CookieFilter) cookieActionCount() int {
	if f.Actions == nil {
		return 0
	}
	return len(f.Actions)
}

func (f *CookieFilter) cookieActionFor(name string) *cookieFilterAction {
	for i := range f.Actions {
		if f.Actions[i].Name == name {
			return &f.Actions[i]
		}
	}
	return nil
}

func (f *CookieFilter) hasCookieAction(name string) bool {
	for _, a := range f.Actions {
		if a.Name == name {
			return true
		}
	}
	return false
}

func (f *CookieFilter) appendCookieAction(action cookieFilterAction) {
	if action.Type == "" {
		return
	}
	f.Actions = append(f.Actions, action)
}

func (f *CookieFilter) parseCookieAction(d *caddyfile.Dispenser) (cookieFilterAction, error) {
	known := f.cookieActionCount()
	cfa := cookieFilterAction{}
	if known < 0 {
		return cfa, d.Errf("unrecognized subdirective %s", d.Val())
	}
	switch d.Val() {
	case "replace":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = replaceAction
		cfa.Name = d.Val()
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Value = d.Val()
	case "hash":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = hashAction
		cfa.Name = d.Val()
	case "delete":
		if !d.NextArg() {
			return cfa, d.ArgErr()
		}
		cfa.Type = deleteAction
		cfa.Name = d.Val()
	default:
		return cfa, d.Errf("unrecognized subdirective %s", d.Val())
	}
	return cfa, nil
}

func (m CookieFilter) filterQueryField(work *cookieWork, in zapcore.Field) zapcore.Field {
	u, err := url.Parse(in.String)
	if err != nil {
		return in
	}
	q := u.Query()
	for _, a := range work.queryActions {
		switch a.Type {
		case replaceAction:
			m.applyQueryReplace(work, q, a)
		case hashAction:
			m.applyQueryHash(work, q, a)
		case deleteAction:
			m.applyQueryDelete(work, q, a)
		}
	}
	u.RawQuery = q.Encode()
	in.String = u.String()
	return in
}

func (m CookieFilter) applyQueryReplace(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 {
		return
	}
	for i := range q[a.Parameter] {
		q[a.Parameter][i] = a.Value
	}
}

func (m CookieFilter) applyQueryHash(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 {
		return
	}
	for i := range q[a.Parameter] {
		q[a.Parameter][i] = hash(a.Value)
	}
}

func (m CookieFilter) applyQueryDelete(work *cookieWork, q url.Values, a queryFilterAction) {
	if len(work.queryActions) == 0 || a.Type != deleteAction {
		return
	}
	q.Del(a.Parameter)
}

func (f *CookieFilter) appendQueryAction(work *cookieWork, action queryFilterAction) {
	if action.Type == "" {
		return
	}
	work.queryActions = append(work.queryActions, action)
}

func (f *CookieFilter) validateQueryActions(work *cookieWork) error {
	for _, a := range work.queryActions {
		if err := a.Type.IsValid(); err != nil {
			return err
		}
		if a.Parameter == "" && len(work.queryActions) == 0 {
			return errors.New("invalid action type")
		}
		if a.Type == replaceAction && a.Parameter != "" && len(work.queryActions) == 0 {
			return errors.New("invalid action type")
		}
	}
	return nil
}

func (f *CookieFilter) unmarshalQueryActions(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		for d.NextBlock(0) {
			qfa := queryFilterAction{}
			switch d.Val() {
			case "replace":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = replaceAction
				qfa.Parameter = d.Val()
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Value = d.Val()
			case "hash":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = hashAction
				qfa.Parameter = d.Val()
			case "delete":
				if !d.NextArg() {
					return d.ArgErr()
				}
				qfa.Type = deleteAction
				qfa.Parameter = d.Val()
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
			f.appendQueryAction(work, qfa)
		}
	}
	return nil
}

func (m CookieFilter) filterIPField(work *cookieWork, in zapcore.Field) zapcore.Field {
	host, _, err := net.SplitHostPort(in.String)
	if err != nil {
		host = in.String
	}
	if net.ParseIP(host) == nil {
		return in
	}
	in.String = m.maskedIPString(work, in.String)
	return in
}

func (m CookieFilter) maskedIPString(work *cookieWork, raw string) string {
	host, port, err := net.SplitHostPort(raw)
	if err != nil {
		host = raw
		port = ""
	}
	ipAddr := net.ParseIP(host)
	if ipAddr == nil {
		return raw
	}
	mask := work.ipMask.v4Mask
	if ipAddr.To4() == nil {
		mask = work.ipMask.v6Mask
		if mask == nil {
			mask = m.parseMaskCIDR(work, work.ipMask.IPv6MaskRaw, 128)
		}
	} else if mask == nil {
		mask = m.parseMaskCIDR(work, work.ipMask.IPv4MaskRaw, 32)
	}
	masked := ipAddr.Mask(mask)
	if port == "" {
		return masked.String()
	}
	return net.JoinHostPort(masked.String(), port)
}

func (m CookieFilter) parseMaskCIDR(work *cookieWork, rawField int, bitLen int) net.IPMask {
	if rawField == 0 {
		return nil
	}
	if bitLen != 32 && bitLen != 128 {
		bitLen = 32
		if work.ipMask.IPv6MaskRaw == rawField && work.ipMask.IPv4MaskRaw != rawField {
			bitLen = 128
		}
	}
	return net.CIDRMask(rawField, bitLen)
}

func (f *CookieFilter) provisionIPMasks(work *cookieWork) error {
	work.ipMask.v4Mask = f.parseMaskCIDR(work, work.ipMask.IPv4MaskRaw, 32)
	work.ipMask.v6Mask = f.parseMaskCIDR(work, work.ipMask.IPv6MaskRaw, 128)
	return nil
}

func (f *CookieFilter) unmarshalIPMasks(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		for d.NextBlock(0) {
			switch d.Val() {
			case "ipv4":
				if !d.NextArg() {
					return d.ArgErr()
				}
				val, err := strconv.Atoi(d.Val())
				if err != nil {
					return d.Errf("error parsing %s: %v", d.Val(), err)
				}
				work.ipMask.IPv4MaskRaw = val
				if val == 0 {
					work.ipMask.v4Mask = nil
				} else {
					work.ipMask.v4Mask = f.parseMaskCIDR(work, val, 32)
				}
			case "ipv6":
				if !d.NextArg() {
					return d.ArgErr()
				}
				val, err := strconv.Atoi(d.Val())
				if err != nil {
					return d.Errf("error parsing %s: %v", d.Val(), err)
				}
				work.ipMask.IPv6MaskRaw = val
				if val == 0 {
					work.ipMask.v6Mask = nil
				} else {
					work.ipMask.v6Mask = f.parseMaskCIDR(work, val, 128)
				}
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
		}
	}
	return nil
}

func (m CookieFilter) filterAndAdd(work *cookieWork, key string, value any) bool {
	filter, ok := m.lookupFieldFilter(work, key)
	if !ok {
		return false
	}
	if work.filterSession.wrapped == nil {
		return true
	}
	filter.Filter(zap.Any(key, value)).AddTo(work.filterSession.wrapped)
	return true
}

func (m CookieFilter) lookupFieldFilter(work *cookieWork, key string) (LogFieldFilter, bool) {
	if work.filterSession.fields == nil {
		return nil, false
	}
	lookup := key
	if work.filterSession.prefix != "" {
		lookup = work.filterSession.prefix + key
	}
	filter, ok := work.filterSession.fields[lookup]
	return filter, ok
}

func (m CookieFilter) addFilteredString(work *cookieWork, key, value string) {
	if m.filterAndAdd(work, key, value) {
		return
	}
	if work.filterSession.wrapped == nil {
		return
	}
	if caddyhttp.IsCredentialHeader(key) {
		logged := caddyhttp.LoggedHeaderValues(key, []string{value}, true)
		if len(logged) == 1 {
			work.filterSession.wrapped.AddString(key, logged[0])
			return
		}
		joined := caddyhttp.JoinLoggedHeader(caddyhttp.AsLoggableStringArray(logged))
		if joined != "" {
			work.filterSession.wrapped.AddString(key, joined)
			return
		}
	}
	work.filterSession.wrapped.AddString(key, value)
}

func (m CookieFilter) addFilteredArray(work *cookieWork, key string, marshaler zapcore.ArrayMarshaler) error {
	if m.filterAndAdd(work, key, marshaler) {
		return nil
	}
	if work.filterSession.wrapped == nil {
		return nil
	}
	if values, ok := marshaler.(caddyhttp.LoggableStringArray); ok {
		logged := caddyhttp.LoggedHeaderValues(key, []string(values), true)
		return work.filterSession.wrapped.AddArray(key, caddyhttp.AsLoggableStringArray(logged))
	}
	return work.filterSession.wrapped.AddArray(key, marshaler)
}

func (m CookieFilter) addFilteredObject(work *cookieWork, key string, marshaler zapcore.ObjectMarshaler) bool {
