func (f *CookieFilter) provisionNetWriter(work *cookieWork) error {
	repl := caddy.NewReplacer()
	address, err := repl.ReplaceOrErr(work.address, true, true)
	if err != nil {
		return fmt.Errorf("invalid host in address: %v", err)
	}
	work.netAddr, err = caddy.ParseNetworkAddress(address)
	if err != nil {
		return fmt.Errorf("parsing network address '%s': %v", address, err)
	}
	if work.netAddr.PortRangeSize() != 1 {
		return fmt.Errorf("multiple ports not supported")
	}
	if work.dialTimeout < 0 {
		return fmt.Errorf("timeout cannot be less than 0")
	}
	work.sinkKey = work.netAddr.String()
	return nil
}

func (f *CookieFilter) unmarshalNetWriter(work *cookieWork, d *caddyfile.Dispenser) error {
	for d.Next() {
		if !d.NextArg() {
			return d.ArgErr()
		}
		work.address = d.Val()
		work.sinkKey = work.address
		if d.NextArg() {
			return d.ArgErr()
		}
		for nesting := d.Nesting(); d.NextBlock(nesting); {
			switch d.Val() {
			case "dial_timeout":
				if !d.NextArg() {
					return d.ArgErr()
				}
				parsed, err := caddy.ParseDuration(d.Val())
				if err != nil {
					return d.Errf("invalid duration: %s", d.Val())
				}
				timeout := caddy.Duration(parsed)
				if d.NextArg() {
					return d.ArgErr()
				}
				work.dialTimeout = timeout
			default:
				return d.Errf("unrecognized subdirective %s", d.Val())
			}
		}
	}
	return nil
}

