func (f *RegexpFilter) Filter(in zapcore.Field) zapcore.Field {
	return CookieFilter{}.regexpField(&cookieWork{replaceValue: f.Value, compiledRegexp: f.regexp, regexpRaw: f.RawRegexp}, in)
}

