// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	original, ok := in.Interface.(caddyhttp.LoggableStringArray)
	if !ok {
		original = caddyhttp.LoggableStringArray{in.String}
	}
	out := make(caddyhttp.LoggableStringArray, 0, len(original))
	for _, vc := range original {
		originRequest := http.Request{Header: http.Header{"Cookie": []string{vc}}}
		cookies := originRequest.Cookies()
		transformedRequest := http.Request{Header: make(http.Header)}

	OUTER:
		for _, c := range cookies {
			for _, a := range m.Actions {
				if c.Name != a.Name {
					continue
				}

				switch a.Type {
				case replaceAction:
					c.Value = a.Value
					transformedRequest.AddCookie(c)
					continue OUTER

				case hashAction:
					c.Value = hash(c.Value)
					transformedRequest.AddCookie(c)
					continue OUTER

				case deleteAction:
					continue OUTER
				}
			}

			transformedRequest.AddCookie(c)
		}

		out = append(out, transformedRequest.Header.Get("Cookie"))
	}

	in.String = strings.Join(out, "; ")
	in.Interface = out

	return in
}

